package com.course.platform.service.impl;

import com.course.platform.common.exception.BusinessException;
import com.course.platform.domain.entity.*;
import org.junit.jupiter.api.*;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import org.springframework.test.util.ReflectionTestUtils;
import java.math.BigDecimal;
import java.time.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 续期直接复用原支付及结算夹具，验证连续期限、同来源幂等及资格资金唯一认领。 */
class CoursePrivateRenewalTransactionTest {
    CoursePrivateSettlementTransactionTest f;
    CoursePrivateRenewalService service;
    Long sourceId;
    @BeforeEach void setup() throws Exception {
        f=new CoursePrivateSettlementTransactionTest();f.setup();sourceId=f.f.current().getId();
        f.f.config.getRules().setRenewalAuto(true);snapshot();
        var authority=mock(com.course.platform.infra.persistence.mapper.UserAuthorityMapper.class);when(authority.findAuthoritiesByUserId(8L)).thenReturn(java.util.List.of("course-private-contract:review"));
        var target=new CoursePrivateRenewalService(f.f.f.users,f.f.f.contracts,f.f.f.wallets,f.f.terms,f.f.versions,f.f.applications,f.f.allocations,f.f.events,f.service,new CoursePrivateOperationsAccess(f.f.f.users,authority),f.f.json,new CoursePrivateOperationsTime(f.f.clock));
        ReflectionTestUtils.setField(target,"enabled",true);ReflectionTestUtils.setField(target,"automaticEnabled",true);
        var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.f.f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));service=(CoursePrivateRenewalService)proxy.getProxy();
        ReflectionTestUtils.setField(f.f.service,"renewal",service);
    }
    void snapshot() throws Exception {String value=f.f.json.writeValueAsString(f.f.config);f.f.f.jdbc.update("UPDATE course_private_contract_term SET config_snapshot=? WHERE id=?",value,sourceId);f.f.f.jdbc.update("UPDATE course_private_plan_version SET config_snapshot=? WHERE id=1",value);}
    @AfterEach void clear(){f.clear();}
    void qualify(){f.complete(f.buy("first"));f.complete(f.buy("second"));}
    CoursePrivateContractTerm renew(){return service.renewAutomatic(sourceId);}
    CoursePrivateContractTerm source(){return f.f.terms.selectById(sourceId);}
    Long application(){var app=f.f.applications.selectById(1L);app.setId(null);app.setRequestKey("review_renewal");app.setApplicationType("RENEW");app.setContractId(source().getContractId());app.setSourceTermId(sourceId);app.setVersionId(1L);app.setEffectivePolicy("NEXT_TERM");app.setStatus("PENDING");app.setVersion(0);app.setReviewedAt(null);app.setReviewedBy(null);f.f.applications.insert(app);return app.getId();}
    CoursePrivateApplicationService applicationService(){
        var authority=mock(com.course.platform.infra.persistence.mapper.UserAuthorityMapper.class);when(authority.findAuthoritiesByUserId(8L)).thenReturn(java.util.List.of("course-private-contract:review"));
        var target=new CoursePrivateApplicationService(f.f.f.users,f.f.products,f.f.plans,f.f.versions,f.f.applications,f.f.f.contracts,f.f.terms,f.f.service,mock(CoursePricingService.class),new CoursePrivateOperationsAccess(f.f.f.users,authority),f.f.json,new CoursePrivateOperationsTime(f.f.clock));
        ReflectionTestUtils.setField(target,"enabled",true);ReflectionTestUtils.setField(target,"renewal",service);var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.f.f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));return (CoursePrivateApplicationService)proxy.getProxy();
    }
    @Test void stoppedNewSalesAndNewCurrentVersionPreserveSameVersionRenewalApplication(){qualify();f.f.clock.advance(Duration.ofDays(24));f.f.f.jdbc.update("UPDATE course_private_plan SET status='DISABLED',current_version_id=99,visible_to_agents=FALSE");var applications=applicationService();var request=new com.course.platform.domain.dto.CoursePrivateApplicationRequest();request.setPlanId(1L);request.setPlanVersionId(1L);request.setApplicationType("RENEW");request.setSourceTermId(sourceId);request.setEffectivePolicy("NEXT_TERM");request.setRequestKey("stopped_renew");request.setReason("确认原套餐连续续期");f.f.auth(7);var app=applications.submit(7L,request);assertEquals("PENDING",app.get("status"));f.f.auth(8);assertEquals("APPROVED",applications.review((Long)app.get("id"),0,8L,true,"保留原冻结续期规则").get("status"));assertEquals(1L,f.f.terms.selectByRenewalSource(sourceId).getVersionId());}
    @Test void failedPendingQualificationCannotApproveApplicationOrMoveMoney(){Long app=application();f.expire();f.f.auth(8);assertThrows(BusinessException.class,()->service.review(app,0,8L,"尝试审核续期"));assertEquals("PENDING",f.f.applications.selectById(app).getStatus());assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));f.f.f.money("100",f.f.wallet().getBalance());}
    @Test void missingLatestAtBoundaryFallsBackWithImmutableEvidence() throws Exception {qualify();f.f.config.getRules().setRenewalPricePolicy("LATEST_PUBLISHED");snapshot();f.f.f.jdbc.update("UPDATE course_private_plan_version SET effective_until=? WHERE id=1",source().getEndAt());f.expire();var next=renew();assertEquals(1L,next.getVersionId());assertEquals(next.getId(),f.f.events.selectByBizNo("renewal_version_fallback_"+sourceId).getTermId());assertEquals("SAME_VERSION_FALLBACK",f.f.events.selectByBizNo("renewal_version_fallback_"+sourceId).getEventType());}
    @Test void reviewerIdentityAndDatabasePermissionAreRequired(){qualify();f.expire();Long app=application();f.f.auth(7);assertThrows(BusinessException.class,()->service.review(app,0,8L,"伪造审核者"));assertThrows(BusinessException.class,()->service.review(app,0,7L,"代理越权审核"));assertEquals("PENDING",f.f.applications.selectById(app).getStatus());assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void manualReviewAndAutomaticExecutionShareOneNext(){qualify();f.expire();Long app=application();var automatic=renew();f.f.auth(8);var manual=service.review(app,0,8L,"审核原周期续期");assertEquals(automatic.getId(),manual.getId());assertEquals("APPROVED",f.f.applications.selectById(app).getStatus());assertEquals(manual.getId(),service.review(app,0,8L,"重试审批").getId());assertEquals(2,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void approvedScheduleActivatesWithAutomaticCreationDisabledAndPurchasesUseNextSnapshot(){qualify();f.f.clock.advance(Duration.ofDays(24));Long app=application();f.f.auth(8);var next=service.review(app,0,8L,"批准连续续期");ReflectionTestUtils.setField(service,"automaticEnabled",false);f.f.clock.advance(Duration.ofDays(6));var selected=f.f.service.effectiveTerm(7L,9L,true);assertEquals(next.getId(),selected.getId());Long order=f.buy("renewed_purchase");assertEquals(next.getId(),f.f.orderRows.selectById(order).getPrivateTermId());f.f.f.money("78.40",f.f.wallet().getBalance());}
    @Test void pendingOrdersAtBoundaryCannotActivateEvenWhenPartialConsumptionMeetsTarget(){qualify();f.buy("unfinished");f.f.clock.advance(Duration.ofDays(24));var next=renew();f.f.clock.advance(Duration.ofDays(6));assertNull(renew());assertNull(f.f.terms.selectById(next.getId()).getActivatedAt());assertThrows(BusinessException.class,()->f.buy("grace_purchase"));}
    @Test void lateExecutionWatermarkRetainsTransfersMadeInNewPeriod() throws Exception {f.f.config.getRules().setMode("TIME_PREPAID");f.f.config.getRules().setRenewalPolicy("NEW_DEPOSIT");f.f.config.getRules().setRenewalConsumptionTarget(BigDecimal.ZERO);f.f.config.getRules().setRenewalDepositAmount(new BigDecimal("50"));snapshot();f.f.clock.advance(Duration.ofDays(24));f.f.deposit("50","old_period");f.f.clock.advance(Duration.ofDays(7));f.f.deposit("50","new_period");var next=renew();f.f.clock.advance(Duration.ofDays(23));var third=service.renewAutomatic(next.getId());assertNotNull(third);assertEquals("SCHEDULED",third.getStatus());f.f.f.money("50",f.f.terms.selectById(next.getId()).getRenewalNetDepositAmount());assertEquals(3,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));}
    @Test void earlyQualificationSchedulesButNeverExtendsOriginalPurchaseWindow(){qualify();f.f.clock.advance(Duration.ofDays(24));var next=renew();assertEquals("SCHEDULED",next.getStatus());assertEquals(source().getEndAt(),next.getStartAt());assertEquals(sourceId,f.f.current().getId());assertNull(next.getActivatedAt());assertNull(source().getFinalizedAt());}
    @Test void finalizedQualificationActivatesContinuousNextWithoutMovingMoney(){qualify();f.expire();var next=renew();assertEquals("ACTIVE",next.getStatus());assertEquals(source().getEndAt(),next.getStartAt());assertEquals(next.getStartAt().plusDays(30),next.getEndAt());assertEquals(next.getId(),f.f.current().getId());assertEquals("RENEWED",source().getStatus());f.f.f.money("85.60",f.f.wallet().getBalance());f.f.f.money("100",next.getQualificationBasisAmount());assertEquals(2,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_reserved_wallet_ledger WHERE biz_type='ORDER'",Integer.class));}
    @Test void lateGraceFulfillmentDoesNotRestartThirtyDays(){Long a=f.buy("first"),b=f.buy("second");f.expire();assertNull(renew());f.f.clock.advance(Duration.ofDays(3));f.complete(a);f.complete(b);var next=renew();assertEquals(source().getEndAt(),next.getStartAt());assertEquals(LocalDateTime.now(f.f.clock).plusDays(27),next.getEndAt());}
    @Test void concurrentWorkersAndRepeatedCallsCreateOneNext() throws Exception {qualify();f.expire();var outcomes=f.f.f.concurrent(this::renew,this::renew);assertEquals(0,outcomes.stream().filter(RuntimeException.class::isInstance).count());var next=renew();assertEquals(2,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_term_event WHERE biz_no=?",Integer.class,"renewal_"+sourceId));assertEquals(next.getId(),f.f.current().getId());}
    @Test void refundBeforeActivationInvalidatesScheduledCandidate(){qualify();f.f.clock.advance(Duration.ofDays(24));var next=renew();var order=f.f.orderRows.selectById(f.f.f.jdbc.queryForObject("SELECT MIN(id) FROM course_order",Long.class));f.f.f.tx.executeWithoutResult(tx->{f.f.f.service.refund(order,8L);f.f.orderRows.markRefunded(order.getId());});f.f.clock.advance(Duration.ofDays(6));assertNull(renew());assertNull(f.f.terms.selectById(next.getId()).getActivatedAt());assertEquals("EXPIRED",f.f.f.contracts.selectByBinding(7L,9L).getStatus());}
    @Test void disabledAutoFlagDoesNotEvaluateOrGrant(){qualify();f.expire();ReflectionTestUtils.setField(service,"automaticEnabled",false);assertNull(renew());assertNull(source().getFinalizedAt());assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void suspendedOrOldGenerationCannotRenew(){qualify();f.expire();f.f.f.jdbc.update("UPDATE course_private_contract SET status='SUSPENDED'");assertNull(renew());f.f.f.jdbc.update("UPDATE course_private_contract SET status='EXPIRED',relation_generation=2");assertNull(renew());}
    @Test void nextAuditFailureRollsBackSettlementAndGrant(){qualify();f.expire();f.f.f.jdbc.execute("ALTER TABLE course_private_term_event ADD CONSTRAINT reject_renew CHECK(event_type<>'RENEWAL_CREATED')");assertThrows(RuntimeException.class,this::renew);assertEquals(1,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));assertNull(source().getFinalizedAt());assertEquals("ACTIVE",f.f.f.contracts.selectByBinding(7L,9L).getStatus());}
    @Test void netNewDepositUsesUnallocatedRealTransfersRatherThanExistingBalance() throws Exception {f.f.config.getRules().setMode("TIME_PREPAID");f.f.config.getRules().setRenewalPolicy("NEW_DEPOSIT");f.f.config.getRules().setRenewalConsumptionTarget(BigDecimal.ZERO);f.f.config.getRules().setRenewalDepositAmount(new BigDecimal("50"));snapshot();f.f.clock.advance(Duration.ofDays(24));assertNull(renew());f.f.deposit("50","renew_funds");var next=renew();assertEquals("SCHEDULED",next.getStatus());assertEquals(2,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_funding_allocation",Integer.class));f.f.f.money("150",f.f.wallet().getBalance());f.f.clock.advance(Duration.ofDays(6));assertEquals("ACTIVE",renew().getStatus());f.f.f.money("50",source().getRenewalNetDepositAmount());assertEquals("NEW_DEPOSIT",next.getQualificationKind());}
    @Test void laterPublishedVersionCannotChangeVersionSelectedAtNextStart() throws Exception {f.f.config.getRules().setRenewalPricePolicy("LATEST_PUBLISHED");snapshot();qualify();f.expire();f.f.clock.advance(Duration.ofDays(3));var latest=new CoursePrivatePlanVersion();org.springframework.beans.BeanUtils.copyProperties(f.f.versions.selectById(1L),latest);latest.setId(2L);latest.setVersionNo(2);latest.setPublishedAt(LocalDateTime.now(f.f.clock));latest.setFixedPrice(new BigDecimal("5"));var config=f.f.json.readValue(latest.getConfigSnapshot(),com.course.platform.domain.dto.CoursePrivatePlanRequest.class);config.getRules().setFixedPrice(new BigDecimal("5"));latest.setConfigSnapshot(f.f.json.writeValueAsString(config));f.f.versions.insert(latest);var next=renew();assertEquals(1L,next.getVersionId());f.f.f.money("7.20",next.getEffectiveFixedPrice());}
    @Test void latestAtBoundaryFreezesPriceButDoesNotInventInitialFunding() throws Exception {f.f.config.getRules().setRenewalPricePolicy("LATEST_PUBLISHED");snapshot();qualify();var latest=new CoursePrivatePlanVersion();org.springframework.beans.BeanUtils.copyProperties(f.f.versions.selectById(1L),latest);latest.setId(2L);latest.setVersionNo(2);latest.setPublishedAt(LocalDateTime.now(f.f.clock));latest.setFixedPrice(new BigDecimal("5"));latest.setInitialDepositAmount(new BigDecimal("800"));var config=f.f.json.readValue(latest.getConfigSnapshot(),com.course.platform.domain.dto.CoursePrivatePlanRequest.class);config.getRules().setFixedPrice(new BigDecimal("5"));config.getRules().setInitialDepositAmount(new BigDecimal("800"));latest.setConfigSnapshot(f.f.json.writeValueAsString(config));f.f.versions.insert(latest);f.f.clock.advance(Duration.ofDays(24));assertNull(renew());f.f.clock.advance(Duration.ofDays(6));var next=renew();assertEquals(2L,next.getVersionId());f.f.f.money("5",next.getEffectiveFixedPrice());f.f.f.money("100",next.getQualificationBasisAmount());f.f.f.money("85.60",f.f.wallet().getBalance());}
}
